SELECT a.credential_id,a.published_version,c.revision FROM mtls_authorities a JOIN credentials c ON c.id=a.credential_id WHERE a.source='generated' AND NOT c.archived AND a.next_action_at<=(SELECT now FROM cutoff) AND NOT EXISTS(SELECT 1 FROM mtls_rotations r WHERE r.ca_id=a.credential_id AND r.phase<>'complete') AND NOT EXISTS(SELECT 1 FROM background_work w WHERE w.id='mtls-ca-publication:'||a.credential_id||':'||a.published_version::text AND w.state IN ('queued','running'))
